import java.io.*;
import java.util.*;

public class Main {
  public static void main(String[] args) throws IOException {
    InputStreamReader isr = new InputStreamReader(System.in);
    BufferedReader br = new BufferedReader(isr);
    PrintWriter pw = new PrintWriter(System.out);
    process(br, pw);
    pw.close();
  }

  static void process(BufferedReader br, PrintWriter pw) throws IOException {
    int n = Integer.parseInt(br.readLine());
    String sStr = br.readLine();
    char[] s = sStr.toCharArray();
    int[] beauty = new int[n];
    String[] parts = br.readLine().split(" ");
    int totalBeauty = 0;
    for (int i = 0; i < n; i++) {
      beauty[i] = Integer.parseInt(parts[i]);
      totalBeauty += beauty[i];
    }

    List<Integer> sameCharIndices = new ArrayList<>();
    int[] charFreq = new int[128];
    char maxFreqChar = 'a';

    for (int i = 0; i < n / 2; i++) {
      if (s[i] == s[n - 1 - i]) {
        sameCharIndices.add(i);
        if (++charFreq[s[i]] > charFreq[maxFreqChar]) {
          maxFreqChar = s[i];
        }
      }
    }

    int result = totalBeauty;
    for (int idx : sameCharIndices) {
      result -= Math.min(beauty[idx], beauty[n - 1 - idx]);
    }

    if (charFreq[maxFreqChar] > sameCharIndices.size() / 2) {
      List<Integer> penalties = new ArrayList<>();
      for (int i = 0; i < n / 2; i++) {
        if (s[i] != s[n - 1 - i] && s[i] != maxFreqChar && s[n - 1 - i] != maxFreqChar) {
          penalties.add(Math.min(beauty[i], beauty[n - 1 - i]));
        }
      }
      Collections.sort(penalties);
      int rem = 2 * charFreq[maxFreqChar] - sameCharIndices.size();
      for (int i = 0; i < rem; i++) {
        result -= penalties.get(i);
      }
    }

    pw.println(result);
  }
}
