#include <bits/stdc++.h>
using namespace std;

void process(istream& in, ostream& out) {
    int n;
    in >> n;
    string sStr;
    in >> sStr;
    vector<char> s(sStr.begin(), sStr.end());
    vector<int> beauty(n);
    int totalBeauty = 0;
    for (int i = 0; i < n; i++) {
        in >> beauty[i];
        totalBeauty += beauty[i];
    }

    vector<int> sameCharIndices;
    vector<int> charFreq(128, 0);
    char maxFreqChar = 'a';

    for (int i = 0; i < n / 2; i++) {
        if (s[i] == s[n - 1 - i]) {
            sameCharIndices.push_back(i);
            if (++charFreq[s[i]] > charFreq[maxFreqChar]) {
                maxFreqChar = s[i];
            }
        }
    }

    int result = totalBeauty;
    for (int idx : sameCharIndices) {
        result -= min(beauty[idx], beauty[n - 1 - idx]);
    }

    if (charFreq[maxFreqChar] > (int)sameCharIndices.size() / 2) {
        vector<int> penalties;
        for (int i = 0; i < n / 2; i++) {
            if (s[i] != s[n - 1 - i] && s[i] != maxFreqChar && s[n - 1 - i] != maxFreqChar) {
                penalties.push_back(min(beauty[i], beauty[n - 1 - i]));
            }
        }
        sort(penalties.begin(), penalties.end());
        int rem = 2 * charFreq[maxFreqChar] - (int)sameCharIndices.size();
        for (int i = 0; i < rem; i++) {
            result -= penalties[i];
        }
    }

    out << result << "\n";
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    process(cin, cout);
    return 0;
}

